H.background();
const w = H.W, h = H.H;
// de Broglie: lambda = h / (m v).  Use an electron-scale mass slider (x10^-31 kg)
// and a velocity slider (x10^6 m/s) so lambda lands in nm/pm range.
const m31 = P.mass;          // x10^-31 kg  (electron ~ 9.11)
const v6 = P.speed;          // x10^6 m/s
const m = m31 * 1e-31;       // kg
const vel = v6 * 1e6;        // m/s
const hSI = 6.626e-34;       // J*s
const p = m * vel;           // momentum, kg*m/s
const lambda = p > 0 ? hSI / p : Infinity;   // metres
const lambda_nm = lambda * 1e9;              // nm
// the particle travels left->right and WRAPS, carrying a wave packet whose
// wavelength on screen shrinks as the real lambda shrinks
const y0 = h * 0.50;
const travel = (t * 0.22) % 1;
const cx = H.lerp(60, w - 60, travel);
// screen wavelength: map real lambda (nm) to pixels, clamped so it stays visible
const screenLambda = H.clamp(lambda_nm * 60, 14, 160);   // px per cycle
const k = H.TAU / screenLambda;
const halfW = 90;
const pts = [];
for (let i = -halfW; i <= halfW; i++) {
  const xx = cx + i;
  if (xx < 30 || xx > w - 30) continue;
  const env = Math.exp(-(i * i) / (2 * 45 * 45));     // Gaussian envelope (the "particle")
  const yy = y0 - 60 * env * Math.cos(k * i - t * 5);
  pts.push([xx, yy]);
}
if (pts.length >= 2) H.path(pts, { color: H.colors.accent, width: 2.5 });
// the particle itself at the packet centre
H.circle(cx, y0, 8, { fill: H.colors.accent2, stroke: H.colors.bg, width: 2 });
H.arrow(cx, y0, cx + 34, y0, { color: H.colors.warn, width: 2.5, head: 8 });
H.text("v", cx + 38, y0 + 4, { color: H.colors.warn, size: 12 });
H.line(40, y0 + 90, w - 40, y0 + 90, { color: H.colors.grid, width: 1 });
// title + readouts
H.text("Wave–particle duality:  λ = h / (m·v)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("m = " + m31.toFixed(2) + "×10⁻³¹ kg    v = " + v6.toFixed(2) + "×10⁶ m/s", 24, 56, { color: H.colors.sub, size: 13 });
H.text("p = m·v = " + p.toExponential(2) + " kg·m/s", 24, 78, { color: H.colors.sub, size: 13 });
if (isFinite(lambda)) {
  H.text("λ = h/p = " + lambda_nm.toFixed(3) + " nm", 24, 98, { color: H.colors.accent, size: 14, weight: 700 });
} else {
  H.text("λ → ∞  (v = 0: a particle at rest has no de Broglie wave)", 24, 98, { color: H.colors.warn, size: 13 });
}
H.text("more momentum → shorter wavelength → more 'particle-like'", 24, h - 18, { color: H.colors.sub, size: 12 });
H.legend([{ label: "wave packet", color: H.colors.accent }, { label: "particle", color: H.colors.accent2 }], w - 175, 28);
